# DRAFT — REFERENCE ONLY. Hand-maintained umbrella formula. Do not
# install directly from this path; this is the spec for the formula
# that should live at `Formula/loom.rb` in the J-Mentiora/homebrew-loom
# tap repo, alongside the four cargo-dist-autogenerated per-crate
# formulas (loom-cli.rb, loom-daemon.rb, loom-mcp.rb, loom-shims.rb).
#
# AC-DIST-03 reference. cargo-dist v0.25 treats each [package] as a
# separate Homebrew application: each crate gets its own `<name>.rb`.
# Loom ships four binaries across four crates, so the autogen output is
# four formulas. To preserve the AC's `brew install J-Mentiora/loom/loom`
# UX, we hand-maintain THIS umbrella formula in the tap that just
# depends_on the four cargo-dist-managed ones. brew resolves the
# dependency chain automatically, so the end-user sees a single command.
#
# Maintenance burden: when bumping the loom version, bump it here too
# (or wire up a small CI step in the tap repo to keep this in sync with
# the per-crate formulas).

class Loom < Formula
  desc "Agent-first browser automation runtime — deterministic Chromium sessions with replay-equal hash chains, MCP-native tools, and a content-addressed action store"
  homepage "https://github.com/J-Mentiora/loom"
  license "MIT OR Apache-2.0"
  version "1.0.0"
  url "https://github.com/J-Mentiora/loom/releases/download/v1.0.0/source.tar.gz"
  # sha256 # {{ source tarball SHA — fill on first release }}

  # The four cargo-dist-autogenerated per-crate formulas live alongside
  # this file in the tap. depends_on resolves them automatically.
  depends_on "J-Mentiora/loom/loom-cli"
  depends_on "J-Mentiora/loom/loom-daemon"
  depends_on "J-Mentiora/loom/loom-mcp"
  depends_on "J-Mentiora/loom/loom-shims"

  def install
    # Umbrella formula has nothing to install of its own — the per-crate
    # deps install the binaries into Homebrew's bin/ as their own
    # post-install step. We document this with a marker file so the
    # formula isn't a no-op (brew complains about empty install).
    (prefix/"INSTALLED.md").write <<~EOS
      Loom umbrella formula — installs loom-cli, loom-daemon, loom-mcp,
      loom-shims via depends_on. See `loom --help` after installation.
    EOS
  end

  def caveats
    <<~EOS
      Loom drives a Chromium subprocess. Install Chromium via:
          brew install --cask chromium

      Or, for replay-bit-equality across machines:
          loom postinstall   # downloads a pinned Chromium build

      First-run smoke test:
          loom doctor

      macOS Gatekeeper note: on first launch, you may see "loom-shim-chromium
      cannot be opened" because the binary isn't yet signed. Workaround:
          System Settings → Privacy & Security → "Open Anyway"
      Code-signing is on the roadmap; tracked in CHANGELOG.
    EOS
  end

  test do
    system "#{HOMEBREW_PREFIX}/bin/loom", "--version"
  end
end
